import{_ as s,c as t,o as a,ag as i}from"./chunks/framework.Ci10AEOF.js";const n="/docs-website/assets/filter_editor.8ZNVhuLE.png",r="/docs-website/assets/transformer_editor.BrlgF-Wl.png",m=JSON.parse('{"title":"Filters and Transformers","description":"Message routing and transformation","frontmatter":{"title":"Filters and Transformers","description":"Message routing and transformation"},"headers":[],"relativePath":"engine/filters_and_transformers.md","filePath":"engine/filters_and_transformers.md","lastUpdated":1793057853000}'),o={name:"engine/filters_and_transformers.md"};function l(d,e,p,h,c,g){return a(),t("div",null,e[0]||(e[0]=[i('<h1 id="filters-and-transformers" tabindex="-1">Filters and Transformers <a class="header-anchor" href="#filters-and-transformers" aria-label="Permalink to &quot;Filters and Transformers&quot;">​</a></h1><p>A filter decides whether a message goes on. A transformer runs a list of steps on the message, which usually reshape it, convert it between formats, or pull values out of it.</p><h2 id="about-filters" tabindex="-1">About filters <a class="header-anchor" href="#about-filters" aria-label="Permalink to &quot;About filters&quot;">​</a></h2><p>Each connector has its own filter. It evaluates a message and produces a boolean result: <strong>true</strong> means the message is <strong>accepted</strong> and continues, <strong>false</strong> means the message is <strong>filtered</strong> and stops.</p><p><img src="'+n+`" alt="The source filter editor with one Rule Builder rule that accepts messages whose MSH-9.1 equals ADT"></p><p>Both source and destination connectors can have filters:</p><ul><li>When a source filter filters a message, it never reaches any destination.</li><li>When a destination filter filters a message, that particular destination skips it, but other destinations on the channel may still process it.</li></ul><h3 id="filter-rules" tabindex="-1">Filter rules <a class="header-anchor" href="#filter-rules" aria-label="Permalink to &quot;Filter rules&quot;">​</a></h3><p>A filter contains one or more <strong>rules</strong> connected by <strong>operators</strong>, either <strong>AND</strong> or <strong>OR</strong>. Standard boolean precedence applies, meaning AND binds more tightly than OR. For instance:</p><blockquote><p>Rule 1 <strong>OR</strong> Rule 2 <strong>AND</strong> Rule 3</p></blockquote><p>is evaluated as: Rule 1 OR (Rule 2 AND Rule 3).</p><h3 id="the-msg-object" tabindex="-1">The &quot;msg&quot; object <a class="header-anchor" href="#the-msg-object" aria-label="Permalink to &quot;The &quot;msg&quot; object&quot;">​</a></h3><p>Before a filter runs, the engine serializes the incoming message, unless its data type is Raw, and exposes it as the <strong>msg</strong> variable. Depending on the data type in use, this could be an E4X XML object, a JavaScript object, or a JavaScript string. The paths on this page assume the HL7 v2.x data type, where the parsed message is XML whose elements are named by segment, field, and component, so PID.3.1 is reached as <code>msg[&#39;PID&#39;][&#39;PID.3&#39;][&#39;PID.3.1&#39;]</code>.</p><h3 id="filter-rule-types" tabindex="-1">Filter rule types <a class="header-anchor" href="#filter-rule-types" aria-label="Permalink to &quot;Filter rule types&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Rule Type</th><th>Description</th></tr></thead><tbody><tr><td><strong>Rule Builder</strong></td><td>A visual rule editor supporting common comparisons like equals, not equals, contains, etc.</td></tr><tr><td><strong>JavaScript</strong></td><td>Write custom logic in JavaScript. Return <code>true</code> to accept the message, <code>false</code> to filter it.</td></tr><tr><td><strong>External Script</strong></td><td>Points to a JavaScript file on the server filesystem</td></tr><tr><td><strong>Iterator</strong></td><td>Iterates over repeating segments or elements, applying child rules to each one</td></tr></tbody></table><h4 id="rule-builder-example" tabindex="-1">Rule Builder example <a class="header-anchor" href="#rule-builder-example" aria-label="Permalink to &quot;Rule Builder example&quot;">​</a></h4><p>To accept only ADT messages:</p><ul><li>Field: <code>msg[&#39;MSH&#39;][&#39;MSH.9&#39;][&#39;MSH.9.1&#39;].toString()</code></li><li>Condition: Equals</li><li>Value: <code>&quot;ADT&quot;</code></li></ul><p>Each value is a JavaScript expression, so literal text needs quotes. An unquoted <code>ADT</code> is read as a variable name, and every message errors with <code>ReferenceError: &quot;ADT&quot; is not defined</code>. Values are compared as text, not as regular expressions: Equals needs an exact match and Contains a substring.</p><h4 id="javascript-rule-example" tabindex="-1">JavaScript rule example <a class="header-anchor" href="#javascript-rule-example" aria-label="Permalink to &quot;JavaScript rule example&quot;">​</a></h4><p>A JavaScript rule runs inside the filter of the connector it belongs to, source or destination, with <code>msg</code> as the parsed inbound message. This rule assumes the HL7 v2.x data type and reads the sending facility from MSH.4.1. The rule&#39;s return value is its result: <code>true</code> accepts the message, <code>false</code> filters it.</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Accept messages from specific sending facilities</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> facility </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> msg[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;MSH&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">][</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;MSH.4&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">][</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;MSH.4.1&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">].</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">toString</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> allowedFacilities </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;HOSP_A&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;HOSP_B&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;LAB_1&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> allowedFacilities.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">indexOf</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(facility) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!==</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><h2 id="about-transformers" tabindex="-1">About transformers <a class="header-anchor" href="#about-transformers" aria-label="Permalink to &quot;About transformers&quot;">​</a></h2><p>A transformer&#39;s steps usually reshape the message, change field values, convert between formats, or pull out data for later steps. Like filters, every connector has its own.</p><p><img src="`+r+`" alt="The source transformer editor with two Mapper steps and a JavaScript step, the selected Mapper step adding patientMrn to the Channel Map"></p><p>Every transformer has an <strong>inbound data type</strong> and an <strong>outbound data type</strong>. When these are the same (e.g., HL7 v2.x in and HL7 v2.x out), you are modifying a message in place. When they differ (e.g., HL7 v2.x in and JSON out), you are performing a format conversion. See <a href="./data_types_and_formats.html">Data Types and Formats</a> for more.</p><p>A transformer is made up of <strong>steps</strong>, and each step runs as JavaScript: for example, setting a field, extracting a value, or running a script you write.</p><h3 id="the-msg-object-1" tabindex="-1">The &quot;msg&quot; object <a class="header-anchor" href="#the-msg-object-1" aria-label="Permalink to &quot;The &quot;msg&quot; object&quot;">​</a></h3><p><code>msg</code> is the same as in filters.</p><h3 id="the-tmp-object" tabindex="-1">The &quot;tmp&quot; object <a class="header-anchor" href="#the-tmp-object" aria-label="Permalink to &quot;The &quot;tmp&quot; object&quot;">​</a></h3><p>When a transformer has an outbound template configured, a second variable called <strong>tmp</strong> becomes available. It starts as that template, and the steps fill it in. For example, a transformer can read fields from <code>msg</code> (an incoming HL7 v2.x message) and place them in <code>tmp</code> (a JSON template), or copy only the fields it needs from the inbound message.</p><h3 id="transformer-step-types" tabindex="-1">Transformer step types <a class="header-anchor" href="#transformer-step-types" aria-label="Permalink to &quot;Transformer step types&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Step Type</th><th>Description</th></tr></thead><tbody><tr><td><strong>Mapper</strong></td><td>Extracts a value from the inbound message and stores it as a named variable in a selected map (defaults to the channel map)</td></tr><tr><td><strong>Message Builder</strong></td><td>Writes a value into a field of <code>msg</code> or <code>tmp</code></td></tr><tr><td><strong>JavaScript</strong></td><td>Runs a script you write</td></tr><tr><td><strong>External Script</strong></td><td>Loads and runs a JavaScript file from the server filesystem</td></tr><tr><td><strong>XSLT Step</strong></td><td>Applies an XSLT stylesheet to a specified XML source and stores the result in the channel map</td></tr><tr><td><strong>Destination Set Filter</strong></td><td>Removes destinations from the message&#39;s destination set, so they do not receive it (source transformer only)</td></tr><tr><td><strong>Iterator</strong></td><td>Loops through repeating segments or elements, executing child steps for each iteration</td></tr></tbody></table><h4 id="mapper-step" tabindex="-1">Mapper step <a class="header-anchor" href="#mapper-step" aria-label="Permalink to &quot;Mapper step&quot;">​</a></h4><p>Pulls a value from the message and saves it as a variable.</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><strong>Variable</strong></td><td>The name under which the value is stored</td></tr><tr><td><strong>Mapping</strong></td><td>The expression to evaluate (e.g. <code>msg[&#39;PID&#39;][&#39;PID.3&#39;][&#39;PID.3.1&#39;].toString()</code>)</td></tr><tr><td><strong>Default Value</strong></td><td>Fallback value when the mapping returns empty. It is a JavaScript expression, so literal text needs quotes, for example <code>&#39;N/A&#39;</code>; an unquoted word is read as a variable name and the step errors</td></tr><tr><td><strong>String Replacement</strong></td><td>Regular Expression and Replace With fields applied to the mapped value. Both fields are JavaScript expressions, so quote them: <code>&#39;[0-9]+&#39;</code> and <code>&#39;N&#39;</code>. An unquoted regular expression is a syntax error, and the channel does not deploy</td></tr><tr><td><strong>Add to</strong></td><td>Which map to store the variable in: Channel Map (default), Connector Map, Global Channel Map, Global Map, or Response Map</td></tr></tbody></table><p>Once mapped, the variable can be accessed in JavaScript using the corresponding map object (e.g., <code>channelMap.get(&#39;variableName&#39;)</code> for Channel Map scope) and in Velocity template fields (such as File Writer paths) with <code>\${variableName}</code>.</p><h4 id="message-builder-step" tabindex="-1">Message Builder step <a class="header-anchor" href="#message-builder-step" aria-label="Permalink to &quot;Message Builder step&quot;">​</a></h4><p>Assigns a value to a field of <code>msg</code>, the message being processed, or of <code>tmp</code>, the outbound message.</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><strong>Message Segment</strong></td><td>The target field in <code>msg</code> or <code>tmp</code> (drag from the message tree)</td></tr><tr><td><strong>Mapping</strong></td><td>The value to assign. Can be a literal, an expression, or a variable reference (e.g. <code>channelMap.get(&#39;variableName&#39;)</code>)</td></tr></tbody></table><h4 id="javascript-step" tabindex="-1">JavaScript step <a class="header-anchor" href="#javascript-step" aria-label="Permalink to &quot;JavaScript step&quot;">​</a></h4><p>This step runs in a transformer with the HL7 v2.x data type on both sides and an HL7 v2.x outbound template loaded, so <code>tmp</code> exists and holds the parsed template. <code>msg</code> is the parsed inbound message. Because a template is set, the transformed message is taken from <code>tmp</code>, not <code>msg</code>. Without a template <code>tmp</code> is not defined and the step would write to <code>msg</code> instead. <code>DateUtil</code> is one of the utility classes the engine imports into every script.</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Reformat the date of birth on its way into the outbound template</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> dob </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> msg[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;PID&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">][</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;PID.7&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">][</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;PID.7.1&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">].</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">toString</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (dob.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">length</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ===</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  tmp[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;PID&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">][</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;PID.7&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">][</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;PID.7.1&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> DateUtil.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">convertDate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;yyyyMMdd&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;yyyy-MM-dd&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, dob);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>With a PID.7 of <code>19800101</code> the outbound message carries <code>1980-01-01</code>.</p><h4 id="iterator-step" tabindex="-1">Iterator step <a class="header-anchor" href="#iterator-step" aria-label="Permalink to &quot;Iterator step&quot;">​</a></h4><p>Handles repeating segments or elements:</p><ol><li>Set <strong>Iterate On</strong> to the repeating element path</li><li>Add child steps (Mapper, Message Builder, JavaScript) inside the iterator</li><li>Use the <strong>Index Variable</strong> to reach the current element</li></ol><h2 id="response-transformers" tabindex="-1">Response transformers <a class="header-anchor" href="#response-transformers" aria-label="Permalink to &quot;Response transformers&quot;">​</a></h2><p>A response transformer exists only on destination connectors. It runs on what the destination got back after it sent, and its steps can do anything a transformer step can.</p><p>In addition to the response content itself, a destination response includes a <strong>status</strong> (e.g., SENT, ERROR), a <strong>status message</strong>, and an <strong>error message</strong>. A response transformer can change any of these. For example, a script that decides an ERROR response is acceptable can set the status to SENT.</p><div class="warning custom-block"><p class="custom-block-title">A response transformer skips most failed sends unless its inbound data type is Raw</p><p>A response transformer runs only when the destination got a response back, or when the response inbound data type is Raw. A failed send usually has no response: a refused connection, an HTTP error with an empty body, and a JavaScript Writer script that throws all skip the response transformer, so error handling written there never runs for them.</p><p>With the response inbound data type set to Raw, the response transformer runs every time, response or not. <code>msg</code> is then the raw response text, so parse it yourself, for example with <code>JSON.parse(msg)</code> or <code>new XML(msg)</code>.</p><p>An HTTP error status such as 500 that comes with a body is a response: the HTTP Sender stores the body as the response, so the response transformer runs whatever the data type.</p></div><h2 id="message-trees" tabindex="-1">Message trees <a class="header-anchor" href="#message-trees" aria-label="Permalink to &quot;Message trees&quot;">​</a></h2><p>The transformer editor provides two tree views of the message structure:</p><table tabindex="0"><thead><tr><th>Tree</th><th>Description</th></tr></thead><tbody><tr><td><strong>Inbound Message Template Tree</strong></td><td>Built from the inbound template, a sample message that is only a reference. A field dragged from it gives its path in <code>msg</code></td></tr><tr><td><strong>Outbound Message Template Tree</strong></td><td>Built from the outbound template, which is what <code>tmp</code> starts as. A field dragged from it gives its path in <code>tmp</code></td></tr></tbody></table><h3 id="using-message-trees" tabindex="-1">Using message trees <a class="header-anchor" href="#using-message-trees" aria-label="Permalink to &quot;Using message trees&quot;">​</a></h3><ul><li><strong>Drag and drop</strong> fields from the inbound tree to create Mapper steps</li><li><strong>Drag and drop</strong> fields from the outbound tree to create Message Builder steps</li><li>Clicking a field only selects it. To get its path expression, drag the field into a step or use the right-click menu</li><li>Load sample messages to populate the tree structure</li></ul><h2 id="execution-order" tabindex="-1">Execution order <a class="header-anchor" href="#execution-order" aria-label="Permalink to &quot;Execution order&quot;">​</a></h2><p>Within one destination chain, the filters, transformers, send, and response transformer run in this order.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Source Filter Rules (in order)</span></span>
<span class="line"><span>    ↓ (if accepted)</span></span>
<span class="line"><span>Source Transformer Steps (in order)</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Destination 1 Filter Rules (in order)</span></span>
<span class="line"><span>    ↓ (if accepted; otherwise the chain continues with Destination 2)</span></span>
<span class="line"><span>Destination 1 Transformer Steps (in order)</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Destination 1 Connector sends message</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Destination 1 Response Transformer Steps (in order)</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Destination 2 Filter Rules, Transformer Steps, send, Response Transformer Steps</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Every later destination in the chain, in the same order</span></span></code></pre></div><p>Destination 2 waits for Destination 1 only when the two share a chain. A destination with <strong>Wait for previous destination</strong> checked, which is the default, joins the chain of the destination above it; one with it unchecked starts a new chain, and chains run at the same time. See <a href="./threading_and_ordering.html#destination-chains">Destination chains</a>. When a destination queues the message instead of sending it on the processing thread, the chain moves on at once, and the send and the response transformer run later on a queue thread. See <a href="./queueing.html#destination-queues">Destination queues</a>.</p>`,60)]))}const k=s(o,[["render",l]]);export{m as __pageData,k as default};
